//! mylar3 tool surface.
//!
//! Endpoint registry: `mylar3.{list, detail, create, update, delete}` —
//! generated by `#[endpoint_resource]`.
//!
//! Detect + remediate:
//!   - `mylar3.status`           search reach, completed-download handling, stuck grabs, torrent wiring
//!   - `mylar3.configure`        fix settings drift through the web settings form (dry run by default)
//!   - `mylar3.backlog.process`  queue Mylar's post-processor over a completed-downloads folder (dry run by default)

use plugin_toolkit::prelude::*;

use crate::acquisition::{ClientProvider, ResolvedDownloadClient};
use crate::api::Mylar;
use crate::execute;
use crate::remediate::{self, BacklogProcess, ConfigureReport};
use crate::status::{self, StatusReport};

#[endpoint_resource(plugin = "mylar3")]
pub struct Mylar3Endpoint {
    pub name: String,
    #[secret]
    pub api_key: String,
    /// Web UI login, needed to read settings when Mylar's web UI uses basic auth.
    pub web_username: Option<String>,
    #[secret]
    pub web_password: Option<String>,
    pub enabled: bool,
}

pub async fn connect(name: &str) -> Result<Mylar> {
    let row = endpoint_db::require(name)?;
    let api_key = plugin_toolkit::secrets::resolve_scoped(
        "mylar3",
        name,
        "api_key",
        (!row.api_key.is_empty()).then_some(row.api_key.as_str()),
    )?;
    let web_auth = match row.web_username.filter(|u| !u.is_empty()) {
        Some(user) => {
            let pass = plugin_toolkit::secrets::resolve_scoped(
                "mylar3",
                name,
                "web_password",
                row.web_password.as_deref(),
            )?;
            Some((user, pass))
        }
        None => None,
    };
    let base_url = route::resolve_reachable(name, &row.routes, false).await?;
    Ok(Mylar::new(&base_url, &api_key, web_auth))
}

pub const DEFAULT_STUCK_HOURS: u32 = 24;

#[orca_struct(args)]
pub struct StatusArgs {
    /// Registered mylar3 endpoint name.
    #[arg(long)]
    pub name: String,
    /// A grab still at Snatched after this many hours counts as stuck.
    #[arg(long, default_value_t = DEFAULT_STUCK_HOURS)]
    #[serde(default = "default_stuck_hours")]
    pub stuck_hours: u32,
}

fn default_stuck_hours() -> u32 {
    DEFAULT_STUCK_HOURS
}

/// Detect drift that silently breaks comics: `usenet_retention` against the
/// oldest Wanted issue, completed-download handling, issues stuck at Snatched,
/// search delay, and torrent search without a configured client. Settings
/// Mylar will not hand over are reported as unknown, with the reason.
#[orca_tool(domain = "mylar3", verb = "status", role = "read")]
async fn mylar3_status(args: StatusArgs, _ctx: &ToolCtx) -> Result<StatusReport> {
    let m = connect(&args.name).await?;
    status::status(&args.name, &m, args.stuck_hours).await
}

#[orca_struct(args)]
pub struct ConfigureArgs {
    /// Registered mylar3 endpoint name.
    #[arg(long)]
    pub name: String,
    /// Days of usenet retention to advertise to indexers (newznab `maxage`),
    /// matched exactly. Omitted, a value below 6000 is raised to 6000 and a
    /// higher one is left alone. Match the shortest retention among your news
    /// providers.
    #[arg(long)]
    #[serde(default)]
    pub usenet_retention: Option<u32>,
    /// Torrent downloader to select and configure: `qbittorrent`, `deluge`,
    /// `transmission`, `rtorrent` or `utorrent`.
    #[arg(long)]
    #[serde(default)]
    pub torrent_client: Option<String>,
    /// Torrent client base URL as Mylar reaches it, e.g. `http://10.0.0.16:8080`.
    #[arg(long)]
    #[serde(default)]
    pub torrent_url: Option<String>,
    #[arg(long)]
    #[serde(default)]
    pub torrent_username: Option<String>,
    /// orca secret holding the torrent client password. Omitted, with
    /// `torrent_username` set, reads `mylar3.<name>.torrent_password`.
    #[arg(long)]
    #[serde(default)]
    pub torrent_password_secret: Option<String>,
    /// Category or label Mylar files torrents under; defaults to `comics`.
    #[arg(long)]
    #[serde(default)]
    pub torrent_category: Option<String>,
    /// Folder the torrent client saves into, as the client sees it.
    #[arg(long)]
    #[serde(default)]
    pub torrent_directory: Option<String>,
    /// Apply. Omitted, reports drift and changes nothing.
    #[arg(long)]
    #[serde(default)]
    pub execute: bool,
}

/// **Fix settings drift**: `usenet_retention` against the target, and
/// `nzb_downloader` when SABnzbd is fully set up but unused (otherwise listed as
/// `manual`), and the torrent downloader when `torrent_client` is given. Mylar's only settings writer is its all-or-nothing web form, so
/// `execute` re-posts every checkbox and provider at its current value with the
/// changes applied, refusing when this Mylar's form does not match. It fails
/// if the settings moved since the plan, or if anything other than the changes
/// moved on write. Without `execute`, reports drift and changes nothing.
#[orca_tool(
    domain = "mylar3",
    verb = "configure",
    role = "admin",
    execute_gated = false
)]
async fn mylar3_configure(args: ConfigureArgs, ctx: &ToolCtx) -> Result<ConfigureReport> {
    const TOOL: &str = "mylar3.configure";
    execute::require_admin(TOOL, ctx)?;
    let torrent = torrent_client(&args)?;
    let m = connect(&args.name).await?;
    remediate::configure(
        &args.name,
        &m,
        args.usenet_retention,
        torrent.as_ref(),
        args.execute,
    )
    .await
}

fn torrent_provider(name: &str) -> Result<ClientProvider> {
    Ok(match name {
        "qbittorrent" => ClientProvider::Qbittorrent,
        "deluge" => ClientProvider::Deluge,
        "transmission" => ClientProvider::Transmission,
        "rtorrent" => ClientProvider::Rtorrent,
        "utorrent" => ClientProvider::Utorrent,
        other => bail!("unknown torrent_client '{other}'"),
    })
}

fn torrent_client(args: &ConfigureArgs) -> Result<Option<ResolvedDownloadClient>> {
    let Some(client) = args.torrent_client.as_deref() else {
        return Ok(None);
    };
    let provider = torrent_provider(client)?;
    let password = match args.torrent_username.as_deref().filter(|u| !u.is_empty()) {
        Some(_) => {
            let secret = args.torrent_password_secret.clone().unwrap_or_else(|| {
                plugin_toolkit::secrets::scoped_name("mylar3", &args.name, "torrent_password")
            });
            Some(plugin_toolkit::secrets::get_required(&secret)?)
        }
        None => None,
    };
    Ok(Some(ResolvedDownloadClient {
        provider: Some(provider),
        name: client.to_string(),
        url: args.torrent_url.clone(),
        username: args.torrent_username.clone(),
        password,
        category: args.torrent_category.clone(),
        client_directory: args.torrent_directory.clone(),
        ..Default::default()
    }))
}

#[orca_struct(args)]
pub struct BacklogArgs {
    /// Registered mylar3 endpoint name.
    #[arg(long)]
    pub name: String,
    /// Completed-downloads folder as Mylar's container sees it, e.g.
    /// `/downloads/completed/comics`.
    #[arg(long)]
    pub folder: String,
    /// Threshold for the stuck-at-Snatched count reported alongside.
    #[arg(long, default_value_t = DEFAULT_STUCK_HOURS)]
    #[serde(default = "default_stuck_hours")]
    pub stuck_hours: u32,
    /// Apply. Omitted, reports the stuck count and queues nothing.
    #[arg(long)]
    #[serde(default)]
    pub execute: bool,
}

/// **Import the backlog**: queue Mylar's post-processor over `folder`
/// (`forceProcess`, `Manual Run`), which matches every file there against the
/// watchlist and moves hits into the library. `folder` must sit inside
/// `sab_directory` or `check_folder` and clear of the library
/// (`destination_dir`). Without `execute`, reports the checked folder and how
/// many issues are stuck at Snatched, and queues nothing.
#[orca_tool(
    domain = "mylar3",
    verb = "backlog.process",
    role = "admin",
    execute_gated = false
)]
async fn mylar3_backlog_process(args: BacklogArgs, ctx: &ToolCtx) -> Result<BacklogProcess> {
    const TOOL: &str = "mylar3.backlog.process";
    execute::require_admin(TOOL, ctx)?;
    let m = connect(&args.name).await?;
    remediate::process_backlog(&args.name, &m, &args.folder, args.stuck_hours, args.execute).await
}

#[cfg(test)]
mod tests {
    use super::*;
    use plugin_toolkit::contract::config::{Config, Model};
    use plugin_toolkit::contract::CallerIdentity;
    use std::path::PathBuf;
    use std::sync::Arc;

    fn ctx(role: Option<&str>) -> ToolCtx {
        let cfg = Arc::new(Config {
            anthropic_api_key: None,
            lmstudio_url: String::new(),
            ollama_url: String::new(),
            default_model: Model::LMStudio {
                id: String::new(),
                url: String::new(),
            },
            app_dir: PathBuf::from("/nonexistent"),
            memory_root: PathBuf::from("/nonexistent"),
            db_path: PathBuf::from("/nonexistent/orca.db"),
            ports: Default::default(),
        });
        let ctx = ToolCtx::new(cfg);
        match role {
            Some(role) => ctx.with_auth(CallerIdentity {
                user_id: "u".into(),
                username: "op".into(),
                role: role.into(),
                can_mutate: true,
            }),
            None => ctx,
        }
    }

    // The role check runs before the endpoint lookup, so these never reach a
    // registry or a Mylar.
    #[tokio::test]
    async fn configure_requires_admin_on_dry_run() {
        for role in [Some("user"), None] {
            let args = ConfigureArgs {
                name: "m".into(),
                usenet_retention: None,
                torrent_client: None,
                torrent_url: None,
                torrent_username: None,
                torrent_password_secret: None,
                torrent_category: None,
                torrent_directory: None,
                execute: false,
            };
            let err = mylar3_configure(args, &ctx(role))
                .await
                .unwrap_err()
                .to_string();
            assert!(err.starts_with("mylar3.configure"), "{err}");
        }
    }

    #[test]
    fn torrent_provider_names() {
        assert_eq!(
            torrent_provider("qbittorrent").unwrap(),
            ClientProvider::Qbittorrent
        );
        assert!(torrent_provider("sabnzbd").is_err());
    }

    #[tokio::test]
    async fn backlog_requires_admin_on_dry_run() {
        for role in [Some("user"), None] {
            let args = BacklogArgs {
                name: "m".into(),
                folder: "/downloads/complete".into(),
                stuck_hours: DEFAULT_STUCK_HOURS,
                execute: false,
            };
            let err = mylar3_backlog_process(args, &ctx(role))
                .await
                .unwrap_err()
                .to_string();
            assert!(err.starts_with("mylar3.backlog.process"), "{err}");
        }
    }
}
